  @state viewCols = 0  @ 48
  @state viewRows = 0  @ 49
  @state gridPainter = nil  @ 50   -- cell painter, rebuilt each frame in drawTracker; hit-test reads its fromScreen so draw and hit can't drift
  @state chanLeft, chanWidth, totalWidth = {}, {}, 0  @ 52
  @state ctx, gridFont, uiFont = gui.ctx, gui.font, gui.uiFont  @ 71
  @state dragging = false  @ 72   -- tracker-grid selection drag: click → held → release
  @state laneConsumed = false  @ 74
  @state paintLast = nil  @ 76   -- region-paint per-cell debounce
  @state renderFns = {  @ 175
  @state VNAME_MAX = 14  @ 291
  @state laneRenderable = { cc = true, pb = true, at = true }  @ 361
      @invariant  lane strip renders only cc/pb/at; other types show as tinted background  @ 360
  @state LANE_ROW_MIN = 3  @ 363
  @state LANE_ROW_MAX = 32  @ 364
  @state PART_LABEL = { pitch = 'PITCH', sample = 'SAMP', vel = 'VEL', delay = ...  @ 493
      @contract  assumes computeLayout ran this frame; reads chanLeft/Width/Order, gridOriginX/Y  @ 490
  @state NO_OVERLAY = { notes = {}, hidden = {} }  @ 509   -- the hostless frame: no ghosts, nothing suppressed
  @state editKeys = {}  @ 853
  @state lastEditKey  @ 871
  @state gridPane = {}  @ 875

# Private functions
  @fn layoutColumns(cols, scrollCol)  @ 55-69
      @contract  clears col.x on every col before assigning; off-screen cols stay nil  @ 54
  -- Cell renderers
  @fn renderNote(evt, col, row)  @ 80-147
  @fn renderPB(evt)  @ 149-154
  @fn renderCC(evt, col)  @ 156-163
  @fn renderFx(_, col, row)  @ 167-173
      -- The region's chain, one stage per row from the badge down, resolved off the registry as the
      -- view minted the stack; live stages keep the cell's default colour, bypassed ones dim like the fx tab.
  @fn renderCell(evt, col, row)  @ 185-188
  @fn delayMarkerOffset(col, pitchWidth)  @ 192-194
      -- Offset of the gap before the 3 delay digits in a note cell (* marker slot).
      -- Layout: pitch(W) + optional sample(3) + ' ' + vel(2); W = active pitchWidth.
  @fn fxMarkerOffset(col, pitchWidth)  @ 198-200
      -- The fx badge sits in the pre-vel separator slot -- one column inboard of
      -- the delay-marker slot, so the two markers never collide.
  -- Drawing
  @fn printer(x0, y0)  @ 206-271
      -- Cell adapter over the shared painter: col/row → screen via one transform.
      -- cellW/cellH are odd integers (whole-pixel landing); snap handles fractional cases.
  @fn laneStripRows()  @ 274-277
      @contract  returns 0 when laneStrip.visible is false; layout and draw branch on this  @ 273
  @fn drawLocalScrim(draw, hole, w, h)  @ 281-287
      -- Local-mode wash: dim the whole grid except a hole at the instance the caret sits
      -- inside (`hole`, grid units); nil hole washes everything. Overlays the cell pass.
  @fn vnameSize()  @ 293
  @fn vnameGap()  @ 297
      -- Bottom gap under a vertical name, in rows: clear of the grid's top rule
      -- with a couple of px of breathing room.
  @fn vname(label)  @ 301-326
      -- Rotated param name, trimmed to fit the fixed header. Binary search finds
      -- the longest prefix whose rotated strip fits, exact under variable-width fonts.
  @fn ensureCellSize()  @ 330-338
      -- cellW/cellH: odd px so 1px strokes land on pixel centres. Lazy: first layout or measure.
      -- Measure under the grid font: naturalWidth() may trigger this before draw's font push.
  @fn computeLayout(budgetW, budgetH)  @ 343-356
      -- RESERVE_ROWS of breathing is kept clear at the bottom for every caller; the grid fills the rest.
      @contract  must run before draws reading chanLeft/chanWidth/totalWidth/viewRows  @ 340
      @contract  calls tv:setGridSize so tv scroll math sees the live viewport  @ 341
  -- Lane strip
  @fn curveEditorFrame(col, colIdx, rect, tMin, tMax, hovered)  @ 368-413
      -- Build the curve-editor FrameArgs for `col` over row-space [tMin,tMax] in `rect`; returns
      -- true iff it consumed the mouse. Shared by the lane strip and the pattern editor's curve pane.
  @fn drawLaneStrip()  @ 417-488
      @contract  publishes laneConsumed=true if curve editor claimed input this frame  @ 415
      @contract  handleMouse short-circuits on laneConsumed  @ 416
  @fn notePartHeaders(col)  @ 495-507
  @fn drawTracker(host)  @ 511-821
  -- Input
  @fn cellAt(mouseX, mouseY)  @ 827-830
      -- Screen point -> (fractional column, integer row) through the grid painter's
      -- inverse, so a click resolves against the exact transform the draw pass used.
  @fn nearestStop(mouseX, mouseY)  @ 834-849
      @contract  returns (col, stop, fracX) or (nil, nil, fracX)  @ 832
      @invariant  fracX is separate so callers distinguish 'past last col' from 'inside col N'  @ 833
  @fn add(key, byte, digit)  @ 855

# Public API (gridPane:*)
  @api gridPane:draw(gridW, gridH, host)  @ 881-888
      -- Draw pass: computeLayout twice (lane-drag callbacks may rebuild grid.cols,
      -- so drawTracker needs a fresh layout), with the grid font pushed throughout.
      @contract  host (the frame's resolved fx host) ghosts its chain's derived notes into the grid  @ 879
      @invariant  lane-strip drag callbacks may flush tv.grid.cols and clear col.x  @ 880
  @api gridPane:geom()  @ 891-893
      -- Grid geometry for the host's help:anchor (which spans grid + palette).
  @api gridPane:naturalWidth()  @ 897-902
      -- Intrinsic pixel width of the current grid (gutter + every column). Lets the pattern
      -- editor size the grid to its exact content and hand the rest of the width to the curve.
  @api gridPane:heightForRows(rows)  @ 906-909
      -- Content-region pixel height for `rows` grid rows (header, lane strip, bottom breathing);
      -- inverts computeLayout. +2px cancels its RESERVE subtraction so pixel rounding can't clip the last row.
  @api gridPane:cellHeight()  @ 911
  @api gridPane:cellWidth()  @ 912
  @api gridPane:drawCurveEditor(rect)  @ 917-960
      -- time -> X across the grid's scrolled window, so scrolling pans/zooms the curve and a
      -- fitting pattern shows whole; assumes gridPane:draw ran first this frame (reads viewRows).
      @contract  renders the current column's curve into `rect`; sets laneConsumed  @ 914
  @api gridPane:handleMouse()  @ 966-1101
  @api gridPane:handleKeys(kr)  @ 1111-1163
      -- commandHeld gates note entry per key: a key bound to both a command and note
      -- entry (e.g. '.' = delete) fires the command; unrelated keys still enter.

